public void register() {
   try {
      if(plan.enrollToPlan()) {
         System.out.println("Customer enrolled to Plan");
      } else {
         throw new Exception("Exception.UNREGISTERED_CUSTOMER");
      }
   } catch(Exception e) {
      Logger LOGGER = LogManager.getLogger(this.getClass());
      LOGGER.error(e.getMessage(), e);
   }
}

public String register(String planName) {
   if(plan.enrollToPlan(planName)) {
      return "Customer enrolled to Plan";
   } else {
      throw new Exception("Customer not registered!");
   }
}

@Component
@Aspect
public class LoggingAspect {
   public static final Logger LOGGER = LogManager.getLogger(LoggingAspect.class);

   @AfterThrowing(pointcut = "execution(* com.infy.bean.*.*(..))",throwing = "exception")
   public void afterThrowing(Exception exception) {
      LOGGER.error(exception.getMessage(), exception);
   }
}

@Before("execution(* com.infy.service.CustomerServiceImpl.fetchCustomer(..))")
public void logBeforeAdvice(JoinPoint joinPoint) {
   logger.info("Joinpoint: {}", joinPoint.getSignature());
}

@AfterReturning(pointcut = "execution(* com.infy.service.CustomerServiceImpl.fetchCustomer(..))", returning = "result")
public void logAfterReturning(JoinPoint joinPoint, String result) {
   logger.info("Return: {}", result);
}

@AfterThrowing(pointcut = "execution(* com.infy.service.CustomerServiceImpl.fetchCustomer(..))", throwing = "exception")
public void logAfterThrowingAdvice(JoinPoint joinPoint, Exception exception) {
   logger.error("Exception: {}", exception.getMessage());
}

@Around("execution(* com.infy.service.CustomerServiceImpl.fetchCustomer(..))")
public Object aroundAdvice(ProceedingJoinPoint joinPoint) throws Throwable {
   logger.info("Before execution");
   Object result = joinPoint.proceed();
   logger.info("After execution");
   return result;
}

@Before("com.infosys.aop.CommonAOP.logFetchCustomer()")
public void updateLog(JoinPoint joinPoint) {
   logger.info("Logging from reused pointcut");
}

